fix.code:
@Configuration
class DataSourceConfig {
    @Bean
    @ConfigurationProperties("spring.datasource.hikari")   // bind hikari.* vào object trả về
    HikariDataSource dataSource(DataSourceProperties props, SecretClient secrets) {
        HikariDataSource ds = props.initializeDataSourceBuilder()
                .type(HikariDataSource.class)
                .password(secrets.get("orders-db-password"))
                .build();
        return ds;
    }
}

// Hoặc không khai báo bean: đưa secret vào nguồn cấu hình
// spring.config.import: optional:configtree:/etc/secrets/
// rồi file /etc/secrets/spring.datasource.password chứa password
